mapper.select:
SELECT o.order_id AS orderId, o.buyer_id AS buyerId, buyer.username AS buyerName, buyer.address AS buyerAddress, o.seller_id AS sellerId, seller.username AS sellerName, seller.address AS sellerAddress, o.total_amount AS totalAmount, o.status, o.created_at AS createdAt FROM orders o LEFT JOIN users buyer ON o.buyer_id = buyer.user_id LEFT JOIN users seller ON o.seller_id = seller.user_id
AND o.order_id = #{orderId}
AND o.buyer_id = #{buyerId}
AND buyer.username LIKE CONCAT('%', #{buyerName}, '%')
AND seller.username LIKE CONCAT('%', #{sellerName}, '%')
AND o.status = #{status}
ORDER BY o.created_at DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM orders o LEFT JOIN users buyer ON o.buyer_id = buyer.user_id LEFT JOIN users seller ON o.seller_id = seller.user_id
AND o.order_id = #{orderId}
AND o.buyer_id = #{buyerId}
AND buyer.username LIKE CONCAT('%', #{buyerName}, '%')
AND seller.username LIKE CONCAT('%', #{sellerName}, '%')
AND o.status = #{status}

